def readiness(report):
    defects = report['open_defects']
    blockers, risks = [], []
    if any(d['severity'] == 'critical' for d in defects):
        blockers.append('critical defect open')
    if any(d['severity'] == 'high' and not d['workaround'] for d in defects):
        blockers.append('high defect without workaround')
    if not report['rollback_tested']:
        blockers.append('rollback not tested')
    if blockers:
        return ('NO GO', blockers)
    if any(d['severity'] == 'high' and d['workaround'] for d in defects):
        risks.append('high defect with workaround')
    if report['risk_coverage_pct'] < 95:
        risks.append('risk coverage below 95%')
    if report['perf_p95_ms'] > report['perf_target_ms']:
        risks.append('performance target missed')
    return ('GO WITH RISKS', risks) if risks else ('GO', [])
